import{J as e,dt as t,j as n,q as r}from"./chunks/framework.767A_6fc.js";import"./chunks/assets.Dg-KBxrH.js";var i=JSON.parse(`{"title":"自建小程序教程","description":"","frontmatter":{},"headers":[],"relativePath":"advance/no-open/develop.md","filePath":"advance/no-open/develop.md","lastUpdated":1782390088000}`),a={name:`advance/no-open/develop.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="自建小程序教程" tabindex="-1">自建小程序教程 <a class="header-anchor" href="#自建小程序教程" aria-label="Permalink to “自建小程序教程”">​</a></h1><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>非开源版小程序，原则上仅用于自己和同学朋友使用。<br> 明确禁止用于除微信官方广告以外的牟利（包括但不限于倒卖、引流其他产品等），除非分我。</p></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">提示</p><p>开发者依靠激励广告获得收益，这是我们更新的动力！<br> 不支持去除广告、公众号卡片，正式版仅允许更换轮播图（需要图床链接）。</p></div><h2 id="一、前置步骤" tabindex="-1">一、前置步骤 <a class="header-anchor" href="#一、前置步骤" aria-label="Permalink to “一、前置步骤”">​</a></h2><ol><li>注册小程序 <a href="https://mp.weixin.qq.com" target="_blank" rel="noreferrer">微信公众平台</a></li><li>设置小程序名称、简称、简介、图标（随便填写）</li><li>设置小程序类目、主营类目 (推荐类目写在下面)</li></ol><details class="details custom-block"><summary>如果需要发布线上版本</summary><ol><li>注册小程序 <a href="https://mp.weixin.qq.com" target="_blank" rel="noreferrer">微信公众平台</a></li><li>设置小程序名称、简称、简介、图标（随便填写）</li><li>设置小程序类目、主营类目 (推荐类目写在下面)</li><li>小程序备案 (免费，必须) + 小程序微信认证 (非企业30元/年，可选)</li><li>申请小程序开发接口 (至少需要 <code>wx.chooseLocation</code>，可选 <code>wx.getLocation</code>)</li></ol></details><p>推荐的小程序类目（没特殊需要就照着选）</p><blockquote><p>教育服务 &gt; 在线教育<br> 工具 &gt; 办公<br> 工具 &gt; 计算器<br> 体育 &gt; 在线健身<br> 工具 &gt; 信息查询</p></blockquote><h2 id="二、填问卷自动上传小程序代码" tabindex="-1">二、填问卷自动上传小程序代码 <a class="header-anchor" href="#二、填问卷自动上传小程序代码" aria-label="Permalink to “二、填问卷自动上传小程序代码”">​</a></h2><p>完成小程序注册流程后，<a href="./upload">点击前往填写问卷</a>，记得关闭 IP 白名单，否则无法上传代码。</p><img src="/image/guide/%E5%B0%8F%E7%A8%8B%E5%BA%8F%E5%AF%86%E9%92%A5.png" style="width:min(60vw, 360px);"><h2 id="三、后置步骤" tabindex="-1">三、后置步骤 <a class="header-anchor" href="#三、后置步骤" aria-label="Permalink to “三、后置步骤”">​</a></h2><p>在 <code>账号设置</code> &gt; <code>第三方设置</code> &gt; <code>半屏小程序管理</code> 中添加以下小程序，即可在小程序内打开半屏小程序。</p><ul><li>御坂网络 <code>wxb42fe32e6e071916</code>（推荐）</li><li>腾讯频道 <code>wxf6b0c0f50d040b4c</code></li><li>腾讯文档 <code>wxd45c635d754dbf59</code></li></ul><h2 id="附-常见问题" tabindex="-1">附：常见问题 <a class="header-anchor" href="#附-常见问题" aria-label="Permalink to “附：常见问题”">​</a></h2><h4 id="_1-为什么要自建小程序" tabindex="-1">1. 为什么要自建小程序？ <a class="header-anchor" href="#_1-为什么要自建小程序" aria-label="Permalink to “1. 为什么要自建小程序？”">​</a></h4><p>2024年4月，某人才举报了大量相关小程序，建议自建小程序备用！</p><h4 id="_2-如何修改签到-ip" tabindex="-1">2. 如何修改签到 IP？ <a class="header-anchor" href="#_2-如何修改签到-ip" aria-label="Permalink to “2. 如何修改签到 IP？”">​</a></h4><p>如果您是自建小程序用户，并无偿对公众提供稳定服务，我们支持使用自建的服务器进行签到。<br> 您可以参考 <a href="./../open/server">反代服务器搭建教程</a> 搭建自己的服务器，即可使用服务器 IP 进行签到。 如有使用校内 IP 签到的需求，可以采用 FRP 之类的工具内网穿透（但需保证服务可靠性）。</p>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};